CREATE TABLE document_comment (id UUID PRIMARY KEY DEFAULT uuid_v7(),document_id UUID NOT NULL,author_id UUID NOT NULL,parent_comment_id UUID,anchor_revision_id UUID,anchor VARCHAR(4096),body TEXT NOT NULL,status VARCHAR(16) NOT NULL DEFAULT 'OPEN',created_at TIMESTAMPTZ NOT NULL DEFAULT current_timestamp,updated_at TIMESTAMPTZ NOT NULL DEFAULT current_timestamp,version BIGINT NOT NULL DEFAULT 0,CHECK(status IN ('OPEN','RESOLVED','DELETED','DETACHED')),FOREIGN KEY(document_id) REFERENCES document(id) ON DELETE CASCADE,FOREIGN KEY(parent_comment_id) REFERENCES document_comment(id),FOREIGN KEY(anchor_revision_id) REFERENCES document_revision(id));
CREATE INDEX idx_document_comment_document ON document_comment(document_id,created_at);
